"{
  "name": "Magnetic Field Data Interface",
  "description": "This interface retrieves magnetic field data for a given location using the USGS Geomagnetism Program's web service.",
  "function_name": "get_magnetic_field_info",
  "input_args": {
    "latitude": "The latitude coordinate of the location where you want to get the magnetic field data.",
    "longitude": "The longitude coordinate of the location where you want to get the magnetic field data."
  },
  "return": "A JSON object containing comprehensive information about the magnetic field at the specified location.",
  "depend": "requests library, USGS Geomagnetism Program Web API"
}"

"{
"name": "Selenium Test Automation Interface",
"description": "Automates a browser action (clicking an element) on a webpage and returns a screenshot of the page after the action.",
"function_name": "automate_browser_action",
"input_args": {
    "url": "The URL of the webpage",
    "xpath": "The xpath of the element to be clicked"
},
"return": "A screenshot of the webpage after the action",
"depend": "Selenium WebDriver Python library"
}"

"{
  "name": "UFO Sightings Data Verification Interface",
  "description": "This interface verifies claims of UFO sightings by checking a 'ufo-sightings' dataset from data.gov or other reliable sources. It takes the date and location of the claimed sighting as inputs and returns whether there was a reported sighting at that location on that date.",
  "function_name": "verify_ufo_sighting",
  "input_args": ["date", "location"],
  "return": "Boolean value indicating whether there was a reported sighting at the given location on the given date.",
  "depend": {"libraries": ["pandas"], "dataset": ["'ufo-sightings' dataset from data.gov or other reliable sources"]}
}"

"{
  "name": "Historical Soccer Match Results Interface",
  "description": "An interface to fetch historical soccer match results for a specific team from a given range of years.",
  "function_name": "get_historical_match_results",
  "input_args": {
    "team_name": "The name of the team",
    "start_year": "The start year of the range",
    "end_year": "The end year of the range"
  },
  "return": "A list of match results, each result includes the date of the match, the opponent team, goals scored by the user's team, and goals scored by the opponent team.",
  "depend": {
    "Web APIs": [
      "Football-Data.org API"
    ],
    "Python Libraries": [
      "requests",
      "datetime"
    ]
  }
}"

"{
  "name": "Optimal Pig Feed Calculation Interface",
  "description": "An interface that calculates the optimal feed mix for pigs based on the costs and nutritional values of available feeds and the nutritional needs of the pigs. It uses linear programming to find a solution that minimizes cost while meeting nutritional requirements.",
  "function_name": "calculate_optimal_feed",
  "input_args": {
    "costs": "A list of feed costs per unit",
    "nutritional_values": "A 2D list where each sublist corresponds to a feed type, and every element in the sublist is the nutritional value of that feed",
    "nutritional_needs": "A list of nutritional needs of the pig"
  },
  "return": "A list of quantities of each feed type that provides the required nutrients at the lowest cost",
  "depend": "SciPy's optimization (linear programming) function"
}"

"{
  "name": "Inventory Management Interface",
  "description": "This interface provides useful statistics on inventory such as total inventory value, potential sales value and most stocked item.",
  "function_name": "get_inventory_statistics",
  "input_args": {
    "file_path": "Path to the inventory data CSV file. The CSV file should include columns for 'product_name', 'quantity_in_stock', 'cost_price', and 'selling_price'."
  },
  "return": {
    "total_inventory_value": "Total cost of all items in inventory",
    "potential_sales_value": "Total revenue if all items in inventory are sold at their selling price",
    "most_stocked_item": "The item with the most quantity in stock"
  },
  "depend": "This function leverages the pandas Python library for data handling and calculations."
}"

"{
"name": "Cloud Usage Optimization Interface",
"description": "An interface to interact with AWS Cost Explorer to provide cost and usage reports.",
"function_name": "get_aws_cost_and_usage",
"input_args": {
    "start_date": "The start date for the report in 'YYYY-MM-DD' format.",
    "end_date": "The end date for the report in 'YYYY-MM-DD' format."
},
"return": "A list of dictionaries, each containing the blended cost, unblended cost, and total usage for each day within the specified date range.",
"depend": "Boto3 library, AWS SDK for Python and AWS account"
}"

"{
  "name": "Ghost Sightings Database Interface",
  "description": "An interface to query a database of ghost sightings based on location or type of ghost. Data includes date, location, type of ghost, and description of the sighting.",
  "function_name": "get_ghost_sightings",
  "input_args": {
    "location": "String (optional)",
    "type_of_ghost": "String (optional)"
  },
  "return": "List of dictionaries with each dictionary representing a ghost sighting",
  "depend": "Web API (Ghosts and Haunts API)"
}"

"{
  "name": "Diamond Price Prediction Interface",
  "description": "An interface using a pre-trained model from HuggingFace to predict the price of a diamond based on its carat, cut, color, and clarity.",
  "function_name": "predict_diamond_price",
  "input_args": {
    "carat": "The weight of the diamond. A positive real number.",
    "cut": "The quality of the diamond's cut. A string, e.g., 'Ideal', 'Premium', 'Good', 'Fair', or 'Poor'.",
    "color": "The color of the diamond. A string, e.g., 'D' (best) to 'J' (worst).",
    "clarity": "The clarity of the diamond. A string, e.g., 'IF' (Internally Flawless), 'VVS1' (Very, Very Slightly Included 1), 'VVS2', 'VS1', 'VS2', 'SI1' (Slightly Included 1), 'SI2', or 'I1' (Included 1)."
  },
  "return": "The predicted price range of the diamond. An integer that represents a specific price range.",
  "depend": "HuggingFace transformers library, PyTorch"
}"

"{
"name": "Coordinates to Address Lookup Interface",
"description": "An interface to convert geographic coordinates to the corresponding address using Google Geocoding API.",
"function_name": "get_address_from_coordinates",
"input_args": {
    "lat": "Latitude of the location",
    "long": "Longitude of the location"
},
"return": "The corresponding address of the provided geographic coordinates. Returns 'No address found for the provided coordinates.' if no address could be found.",
"depend": "Google Geocoding API"
}"

"{
"name": "Play Info Extraction",
"description": "This interface extracts information about a play by Jalila Baccar from the web. It returns the publication date, the main characters, and a brief summary of the play.",
"function_name": "get_play_info",
"input_args": ["play_name"],
"return": {"Publication Date": "string", "Characters": "list of string", "Summary": "string"},
"depend": {"python libraries": ["requests", "bs4"]}
}"

"{
"name": "School District Funding Analysis Interface",
"description": "This interface provides total funding, per student funding and total student count for any given school district in the U.S.",
"function_name": "get_school_district_funding",
"input_args": {"school_district": "Name of the school district"},
"return": {"total_funding": "Total funding of the school district", "per_student_funding": "Funding per student in the school district", "total_students": "Total number of students in the school district"},
"depend": {"python libraries": ["requests", "pandas"], "Web APIs": ["U.S. Department of Education API"]}
}"
